ALTER TABLE public.user_roles ADD COLUMN display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100), ADD COLUMN phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30);
CREATE FUNCTION public.prevent_profile_identity_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user='authenticated' AND (new.member_id!=old.member_id OR new.account_type!=old.account_type OR new.email!=old.email OR new.id!=old.id) THEN RAISE EXCEPTION 'Identity fields can only be changed through authentication'; END IF; RETURN new; END $$;
CREATE TRIGGER profile_identity_guard BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.prevent_profile_identity_change();
CREATE FUNCTION public.sync_profile_email() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.email IS DISTINCT FROM old.email THEN UPDATE public.profiles SET email=coalesce(new.email,'') WHERE id=new.id; END IF; RETURN new; END $$;
CREATE TRIGGER ironhaus_email_sync AFTER UPDATE OF email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.sync_profile_email();
CREATE FUNCTION public.can_read_image(path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.otp_verified() AND ((split_part(path,'/',1)=auth.uid()::text) OR EXISTS(SELECT 1 FROM public.gym_records r WHERE r.data::text LIKE '%'||path||'%' AND public.gym_access(r.gym_id)) OR EXISTS(SELECT 1 FROM public.client_programs p WHERE p.user_id=auth.uid() AND p.definition::text LIKE '%'||path||'%')) $$;
ALTER POLICY ironhaus_image_read ON storage.objects USING(bucket_id='ironhaus-images' AND public.can_read_image(name));